functions.body:
block([j:1, r, L:1, g:0], for t:3 step -1 thru 1 do if b[t,1]#0 then j:t,
  r: map(lambda([e], ratsimp(radcan(e/b[j,1]))), b),
  for e in flatten(args(r)) do L: L*denom(e)/sxig(L,denom(e)),
  r: r*L, for e in flatten(args(r)) do g: sxig(g,e), r: r/g,
  if is(b[j,1]<0) then -r else r)
